'use strict';
// GameZoney — banco de perguntas e respostas do assistente do chat (sem IA, sem custo por mensagem).
// Montado com o que foi construído no GameZoney (guia, site, planos, fiscal, concorrentes, atendimento).
// Ao abrir, o site grava estas respostas na tabela bot_answers (as editadas no /admin › Assistente não são trocadas).
// Campos: id (fixo), q (pergunta principal), alt (outras formas de perguntar), kw (palavras-chave fortes),
// a (resposta; {planos} = planos e preços atuais do /admin › Planos), human: true = resposta + chama um especialista.
module.exports = [
  // ---------- site, conta e planos ----------
  {id: 'o-que-e', q: 'O que é o GameZoney?', alt: ['o que o sistema faz', 'para que serve', 'como funciona o gamezoney', 'quero conhecer o sistema', 'me fala do sistema'], kw: ['conhecer', 'serve', 'what', 'que es'],
    a: 'O GameZoney é um sistema de gestão para arenas gamer, lan houses e lojas de PCs, consoles, VR e simuladores. Ele tem duas partes, no mesmo instalador:\n• GameZoney Servidor: no PC da recepção (painel, clientes, recargas, caixa, PDV, estoque, TVs, relatórios).\n• GameZoney Cliente: em cada PC gamer (bloqueia o PC, mostra o tempo, login por nick e senha e limpeza no fim da sessão).\nVocê pode testar grátis por 30 dias, sem cartão: crie sua conta em gamezoney.com.'},
  {id: 'recursos', q: 'Quais são os recursos do sistema?', alt: ['o que tem no sistema', 'funcionalidades', 'funcoes do sistema', 'o que ele faz'], kw: ['recursos', 'funcionalidades', 'funcoes'],
    a: 'Principais recursos:\n• Controle de PCs, consoles (pela TV), VR e simuladores, sem limite de aparelhos.\n• Clientes com saldo de tempo, foto, CPF e importação de outro sistema.\n• Recargas, visitante, caixa, PDV com leitor de código de barras, estoque e pagamento combinado.\n• Fidelidade com medalhas, promoções, Corujão/Viradão e Ranking.\n• Autoatendimento no PC: o cliente cria a conta e paga por PIX na tela do PC.\n• Avisos de fim de tempo, mensagens, ligar os PCs pela rede, controle de impressão.\n• Relatórios, estatísticas e backup automático.\n• No Pro: notas fiscais (NF-e de entrada, NFC-e e NFS-e), app do cliente com conquistas (app.gamezoney.com), logo e cor da arena e Multi-Unidade.\nVeja tudo em gamezoney.com/#recursos.'},
  {id: 'precos', q: 'Quanto custa? Quais são os planos?', alt: ['qual o valor', 'preco do sistema', 'valores dos planos', 'mensalidade', 'quanto e o plano', 'tabela de precos', 'plano anual', 'plano mensal'], kw: ['preco', 'precos', 'valor', 'valores', 'custa', 'planos', 'mensalidade', 'anual', 'mensal', 'standard', 'pro', 'price', 'cost', 'plans', 'precio', 'cuesta', 'planes'],
    a: 'Planos do GameZoney (preços atuais):\n{planos}\nA assinatura é feita no site com cartão de crédito e renova sozinha; você cancela quando quiser em Minha conta. Antes, teste grátis por 30 dias sem cartão: gamezoney.com/#precos.'},
  {id: 'diferenca-planos', q: 'Qual a diferença entre o Standard e o Pro?', alt: ['standard ou pro', 'o que o pro tem a mais', 'qual plano escolher', 'qual plano e melhor', 'diferenca dos planos'], kw: ['diferenca', 'standard', 'pro', 'escolher', 'melhor'],
    a: 'O Standard libera todas as funções do dia a dia, autoatendimento por PIX e controle de impressão, com PCs e consoles ilimitados.\nO Pro tem tudo do Standard e mais: Gerenciamento de NF-e (entrada pelo XML do fornecedor), emissão de NFC-e e NFS-e (Focus NFe), app do cliente com conquistas (app.gamezoney.com), logo e cor da arena e Multi-Unidade (acompanhar várias lojas).\nItens e preços atuais:\n{planos}'},
  {id: 'teste', q: 'Como funciona o teste grátis?', alt: ['tem teste gratis', 'quanto tempo dura o teste', 'quantos dias de teste', 'posso testar', 'periodo de teste', 'demonstracao gratis', 'free', 'gratuito', 'testar o sistema'], kw: ['teste', 'testar', 'gratis', 'gratuito', 'free', 'trial', 'prueba'],
    a: 'São 30 dias grátis, sem cartão de crédito. Crie sua conta em gamezoney.com, baixe o instalador em Minha conta › Downloads e instale o GameZoney Servidor no PC da recepção. No teste você usa as funções essenciais e o autoatendimento por PIX. Controle de impressão, NF-e, Gerenciar App e Multi-Unidade ficam liberados ao entrar com a conta de um plano. Os dias que faltam aparecem em Configuração › Licença.'},
  {id: 'fim-teste', q: 'O que acontece quando o teste termina?', alt: ['acabou o teste', 'teste venceu', 'expirou', 'perco meus dados', 'sistema bloqueou'], kw: ['termina', 'venceu', 'expirou', 'acabou', 'bloqueou', 'bloqueado'],
    a: 'Seus dados continuam guardados. Recargas, sessões novas e vendas ficam bloqueadas até assinar um plano. Depois de assinar, entre com a sua conta em Configuração › Licença e tudo volta a funcionar na hora, sem reinstalar.'},
  {id: 'assinar', q: 'Como assino um plano?', alt: ['como comprar', 'quero assinar', 'como pagar o plano', 'onde compro', 'contratar', 'adquirir'], kw: ['assinar', 'comprar', 'contratar', 'adquirir', 'assino', 'compro'],
    a: 'Em gamezoney.com/#precos, escolha o Standard ou o Pro e o período (mensal ou anual) e clique em Assinar. O pagamento é com cartão de crédito, aqui no site, pelo Mercado Pago. Depois, no GameZoney Servidor, abra Configuração › Licença › Entrar com a conta gamezoney.com (mesmo e-mail e senha do site).'},
  {id: 'pagamento', q: 'Quais formas de pagamento vocês aceitam?', alt: ['aceita pix', 'aceita boleto', 'pagar com pix', 'pagar no cartao', 'cartao de debito', 'parcelar', 'forma de pagamento'], kw: ['pagamento', 'boleto', 'cartao', 'credito', 'debito', 'parcelar', 'parcela', 'payment', 'pago'],
    a: 'A assinatura é paga com cartão de crédito, pelo Mercado Pago, e renova sozinha a cada mês ou ano. Os dados do cartão são digitados direto no Mercado Pago e não passam pelo site da GameZoney. Se precisar de outra forma de pagamento, escreva "falar com especialista".'},
  {id: 'renovacao', q: 'Como funciona a renovação?', alt: ['renova sozinho', 'cobranca automatica', 'renovacao falhou', 'cartao recusado', 'nao renovou'], kw: ['renovacao', 'renova', 'cobranca', 'recusado', 'tolerancia'],
    a: 'A assinatura renova sozinha no cartão a cada mês ou ano. Se a renovação falhar, você tem 7 dias de tolerância para regularizar antes de bloquear recargas, sessões novas e vendas; seus dados ficam guardados.'},
  {id: 'cancelar', q: 'Como cancelo a assinatura?', alt: ['quero cancelar', 'cancelar plano', 'parar a cobranca', 'tem fidelidade de contrato', 'multa para cancelar'], kw: ['cancelar', 'cancelo', 'cancelamento', 'multa'],
    a: 'Você cancela quando quiser em Minha conta › Meu plano. A cobrança automática para e o plano continua valendo até o fim do período já pago. Não há multa. Para trocar de plano ou de período, cancele o atual e assine de novo.'},
  {id: 'reembolso', q: 'Posso pedir reembolso?', alt: ['quero meu dinheiro de volta', 'devolucao', 'arrependimento', 'estorno'], kw: ['reembolso', 'devolucao', 'arrependimento', 'estorno', 'dinheiro'], human: true,
    a: 'Sim: pelo direito de arrependimento, em até 7 dias da contratação (Código de Defesa do Consumidor), mediante pedido pelo Suporte; o plano é encerrado no reembolso. Vou encaminhar para um especialista cuidar do seu pedido.'},
  {id: 'trocar-plano', q: 'Posso trocar do Standard para o Pro?', alt: ['mudar de plano', 'fazer upgrade', 'passar para o pro', 'trocar de mensal para anual'], kw: ['upgrade', 'trocar', 'mudar'],
    a: 'Pode. Cancele a assinatura atual em Minha conta › Meu plano e assine o novo plano ou período (o período já pago continua valendo). Depois, no Servidor, clique em Configuração › Licença › Atualizar plano.'},
  {id: 'desconto', q: 'Tem desconto?', alt: ['faz um precinho', 'cupom de desconto', 'promocao', 'desconto para varias lojas', 'valor especial'], kw: ['desconto', 'cupom', 'promocao', 'negociar'], human: true,
    a: 'Os preços publicados em gamezoney.com/#precos já incluem as ofertas vigentes; o plano anual sai mais em conta que o mensal. Condições especiais (várias unidades, parcerias) são tratadas por um especialista: vou encaminhar o seu pedido.'},
  {id: 'revenda', q: 'Posso revender o GameZoney?', alt: ['ser parceiro', 'representante', 'parceria comercial', 'revendedor'], kw: ['revender', 'revenda', 'parceiro', 'parceria', 'representante', 'revendedor'], human: true,
    a: 'O plano é pessoal e intransferível: não pode ser revendido nem compartilhado. Para parcerias comerciais, vou encaminhar o seu contato a um especialista da GameZoney.'},
  {id: 'nota-assinatura', q: 'Quero a nota fiscal da minha assinatura do GameZoney.', alt: ['nota fiscal do plano que eu paguei', 'nota da minha compra do gamezoney', 'preciso da nota do pagamento da assinatura'], kw: ['paguei', 'minha assinatura'], human: true,
    a: 'Sobre a nota fiscal da sua assinatura, um especialista da GameZoney vai confirmar e responder para você.'},
  {id: 'licenca-ativar', q: 'Como ativo o plano no servidor?', alt: ['entrar com a conta no servidor', 'ativar licenca', 'onde coloco minha conta', 'liberar o plano', 'atualizar plano'], kw: ['ativar', 'ativo', 'licenca', 'liberar'],
    a: 'No GameZoney Servidor, abra Configuração › Licença › Entrar com a conta gamezoney.com e use o mesmo e-mail e senha do site. O plano vale para 1 servidor por conta. Assinou ou trocou de plano? Clique em Atualizar plano. Chave antiga GZ-XXXX? Ela também é ativada em Configuração › Licença.'},
  {id: 'troca-pc', q: 'Troquei o computador da recepção. E agora?', alt: ['mudar o servidor de computador', 'formatei o pc', 'pc novo na recepcao', 'trocar de maquina', 'instalar em outro computador'], kw: ['troquei', 'trocar', 'formatei', 'novo', 'outro', 'computador'],
    a: 'Faça um backup completo no computador antigo (Configuração › Backup), instale o GameZoney Servidor no computador novo, restaure o backup e entre com a sua conta em Configuração › Licença. O sistema pede para confirmar a troca e avisa por e-mail; o plano passa para o computador novo. Restaurando o backup, os PCs reconectam sem nova autorização.'},
  {id: 'conta-senha', q: 'Esqueci a senha do site.', alt: ['nao consigo entrar no site', 'recuperar senha', 'redefinir senha', 'trocar senha da conta'], kw: ['esqueci', 'senha', 'recuperar', 'redefinir'],
    a: 'Em gamezoney.com/entrar.html clique em "Esqueci a senha": o link para criar uma nova chega no seu e-mail. Já está logado? Use Minha conta › Meus dados › Redefinir senha.'},
  {id: 'conta-criar', q: 'Como crio minha conta?', alt: ['cadastro no site', 'fazer cadastro', 'registrar', 'criar login'], kw: ['conta', 'cadastro', 'cadastrar', 'registrar'],
    a: 'Clique em "Testar grátis" no topo do site (gamezoney.com/entrar.html?criar=1) e cadastre com e-mail e senha ou entre com o Google. Depois confirme o e-mail e baixe o instalador em Minha conta › Downloads.'},
  {id: 'download', q: 'Onde baixo o instalador?', alt: ['download do sistema', 'baixar o programa', 'link de download', 'onde baixo'], kw: ['baixar', 'download', 'baixo', 'descargar'],
    a: 'Entre na sua conta e abra Minha conta › Downloads: lá está o GameZoney-Instalador.exe (instalador único: Servidor e/ou Cliente). Baixe sempre em gamezoney.com.'},
  {id: 'guia', q: 'Onde encontro o passo a passo de instalação?', alt: ['manual', 'tutorial', 'guia de instalacao', 'documentacao', 'como instalar passo a passo'], kw: ['guia', 'manual', 'tutorial', 'passo', 'documentacao'],
    a: 'Entre na sua conta e abra o Guia (gamezoney.com/guia): conectar os PCs ao servidor, cadastrar as TVs/consoles e importar clientes, com imagens. O guia completo também vem junto com o programa instalado.'},
  {id: 'idiomas', q: 'O sistema está em quais idiomas?', alt: ['tem em ingles', 'tem em espanhol', 'trocar idioma do painel', 'language'], kw: ['idioma', 'idiomas', 'ingles', 'espanhol', 'frances', 'russo', 'language'],
    a: 'O painel está em Português (Brasil), English, Español, Français e Русский; cada usuário escolhe em Perfil › Idioma. O site está em português, inglês e espanhol (seletor no rodapé).'},
  {id: 'experiencia', q: 'A GameZoney é confiável?', alt: ['quantos clientes vocês tem', 'empresa seria', 'anos de mercado', 'quem usa'], kw: ['confiavel', 'confianca', 'seguro', 'experiencia', 'mercado'],
    a: 'A GameZoney tem 10 anos de experiência no setor de arenas e lan houses. A compra é 100% segura (Mercado Pago, site com HTTPS), o teste é grátis por 30 dias sem cartão e as avaliações de clientes aparecem na página inicial. Siga também @gamezoney_ no Instagram.'},

  // ---------- concorrentes e migração ----------
  {id: 'migrar', q: 'Uso outro sistema. Consigo trazer meus clientes?', alt: ['trocar de sistema', 'migrar do nexcafe', 'migrar do handycafe', 'importar clientes de outro sistema', 'perder meus clientes', 'tenho outro programa'], kw: ['nexcafe', 'handycafe', 'migrar', 'migracao', 'importar', 'outro', 'sistema', 'antigo'],
    a: 'Sim. No sistema antigo, exporte a lista de clientes em Excel ou CSV. No GameZoney, abra Clientes › Importar planilha: ele reconhece Nome, Nick, Tempo, Medalhas de fidelidade, CPF, Telefone, E-mail e Observações. O tempo entra como saldo e as medalhas como saldo da fidelidade; você vê uma prévia antes de importar. Cada cliente cria a própria senha no primeiro acesso ao PC. Os produtos também podem ser importados por planilha. Se precisar, nosso suporte ajuda na migração.'},
  {id: 'concorrente', q: 'Qual a diferença do GameZoney para outros sistemas?', alt: ['por que escolher o gamezoney', 'melhor que o nexcafe', 'comparar com handycafe', 'vantagens', 'diferencial', 'concorrente'], kw: ['diferenca', 'diferencial', 'vantagem', 'vantagens', 'concorrente', 'nexcafe', 'handycafe', 'melhor', 'comparar'],
    a: 'Não comentamos outros sistemas, mas estes são diferenciais do GameZoney:\n• PCs, consoles, VR e simuladores ilimitados em todos os planos.\n• Consoles controlados pela TV (VIDAA ou Android TV/Google TV).\n• Autoatendimento: o cliente cria a conta e paga por PIX na tela do PC, e o tempo entra sozinho.\n• Fidelidade com medalhas, Corujão/Viradão e Ranking.\n• Funciona na rede local mesmo sem internet; queda de internet não encerra sessão.\n• No Pro: NFC-e, NFS-e, NF-e de entrada, Multi-Unidade e servidor na nuvem.\n• Importação de clientes e produtos de outro sistema e teste grátis de 30 dias sem cartão.'},
  {id: 'tempo-migrado', q: 'O tempo que o cliente tem no sistema antigo passa para o GameZoney?', alt: ['saldo dos clientes', 'horas dos clientes', 'creditos antigos'], kw: ['saldo', 'horas', 'tempo', 'creditos'],
    a: 'Passa. Na planilha de importação (Clientes › Importar planilha), a coluna Tempo entra como saldo de cada cliente, e Medalhas de fidelidade como saldo inicial da fidelidade. Nicks que já existem no GameZoney não são alterados.'},

  // ---------- instalação, requisitos e rede ----------
  {id: 'requisitos', q: 'O que preciso para usar?', alt: ['requisitos minimos', 'configuracao minima', 'roda em windows 7', 'precisa de internet', 'qual windows'], kw: ['requisitos', 'requisito', 'windows', 'minimo', 'precisa', 'requirements'],
    a: 'Windows 10 ou 11 de 64 bits no PC da recepção e nos PCs gamers, todos na rede local da arena. Para consoles: TV VIDAA (Hisense/Toshiba) ou Android TV/Google TV na rede. A internet só é usada para entrar com a conta, PIX, notas fiscais e Multi-Unidade: sem internet, o dia a dia continua funcionando.'},
  {id: 'instalar', q: 'Como instalo o GameZoney?', alt: ['instalacao', 'como instalar', 'instalar no pc da recepcao', 'instalar nos pcs'], kw: ['instalar', 'instalacao', 'instalo', 'install', 'setup'],
    a: '1. No PC da recepção, rode o GameZoney-Instalador.exe e marque Servidor (deixe o IP desse PC fixo, com reserva no roteador).\n2. Em cada PC gamer, rode o instalador e marque Cliente, com a conta do Windows dos clientes conectada (conta padrão).\n3. No Painel de controle aparece "PC aguardando autorização": confira o código e clique em Autorizar computador; confirme no PC.\n4. Cadastre as TVs/consoles em Painel de controle › + Nova estação.\nPasso a passo com imagens: gamezoney.com/guia.'},
  {id: 'smartscreen', q: 'O Windows mostrou "O Windows protegeu o computador". É seguro?', alt: ['windows bloqueou o instalador', 'fornecedor desconhecido', 'smartscreen', 'aviso azul do windows'], kw: ['smartscreen', 'protegeu', 'desconhecido', 'aviso'],
    a: 'Sim. Esse aviso azul (SmartScreen) aparece em programas baixados da internet que ainda não têm assinatura digital de código. Baixe sempre em gamezoney.com, clique em "Mais informações" e depois em "Executar assim mesmo".'},
  {id: 'antivirus', q: 'O antivírus bloqueou o GameZoney.', alt: ['antivirus apagou', 'virus', 'defender bloqueou'], kw: ['antivirus', 'virus', 'defender', 'bloqueou'],
    a: 'Baixe o instalador só em gamezoney.com. Se o antivírus bloquear, adicione a pasta do GameZoney às exceções do antivírus e instale de novo com o GameZoney-Instalador.exe. Se continuar, escreva "falar com especialista".'},
  {id: 'pc-nao-conecta', q: 'O PC não encontra o servidor.', alt: ['cliente nao conecta', 'pc nao aparece no painel', 'pc vermelho', 'sem conexao com o servidor', 'nao acha o servidor'], kw: ['conecta', 'conectar', 'encontra', 'aparece', 'vermelho', 'conexao'],
    a: 'Confira: 1) o PC e o servidor estão na mesma rede (ou em faixas privadas ligadas por roteador); 2) no servidor, Configuração › Servidor IP › Atualizar Automático (atualiza o IP e o firewall); 3) no PC, use "Informar IP do servidor" com o IP que aparece em Configuração › Servidor IP; 4) o antivírus não está bloqueando. PC sem conexão fica vermelho no painel, mas a sessão continua contando.'},
  {id: 'ip-mudou', q: 'O IP do servidor mudou.', alt: ['troquei o roteador', 'mudei de cabo para wifi', 'ip do servidor'], kw: ['ip', 'roteador', 'wifi', 'cabo'],
    a: 'Em Configuração › Servidor IP clique em Atualizar Automático: o sistema pega o IP atual e ajusta o firewall. Os PCs reencontram o servidor sozinhos. Para não mudar mais, faça uma reserva de IP para o PC da recepção no roteador.'},
  {id: 'rede-diferente', q: 'Os PCs estão em outra rede/roteador. Funciona?', alt: ['outra faixa de ip', 'dois roteadores', 'sub-rede diferente'], kw: ['faixa', 'subrede', 'roteadores', 'rede'],
    a: 'Funciona. O Cliente procura o servidor também nas faixas vizinhas e você pode usar "Informar IP do servidor" no PC. O firewall do GameZoney aceita as redes privadas (192.168.x.x, 10.x.x.x, 172.16–31.x.x).'},
  {id: 'nuvem', q: 'O sistema funciona na nuvem ou pelo celular?', alt: ['acessar de casa', 'acessar de fora', 'ver pelo celular', 'servidor online', 'app'], kw: ['nuvem', 'celular', 'fora', 'remoto', 'casa', 'app', 'online'],
    a: 'O GameZoney funciona na rede local da arena (mais rápido e não para sem internet). Para acompanhar de fora: no Pro, o app da recepção abre o painel do servidor pelo navegador do celular ou de outro computador (app.gamezoney.com/servidor/endereço-da-arena; todas as telas menos Configuração e Gerenciar App), Multi-Unidade mostra faturamento, caixa e PCs em uso de cada loja em Minha conta › Unidades (celular ou computador), e o app do cliente (app.gamezoney.com/endereço-da-arena) mostra aos seus clientes saldo, estações livres, conquistas e histórico pelo celular, sem precisar de domínio nem VPS.'},

  // ---------- PCs, TVs e consoles ----------
  {id: 'consoles', q: 'Como controla os consoles?', alt: ['playstation', 'xbox', 'controle de console', 'controla a tv', 'ps5'], kw: ['console', 'consoles', 'playstation', 'xbox', 'ps5', 'ps4', 'tv', 'hisense', 'vidaa', 'android'],
    a: 'Os consoles são controlados pela TV: TV VIDAA (Hisense/Toshiba) ou Android TV/Google TV na rede. Cadastre a TV em Painel de controle › + Nova estação (tipo Console, IP da TV, entrada HDMI e sistema da TV) e use Parear TV. Ao iniciar a sessão, a TV troca para a entrada HDMI do console; ao terminar, mostra a tela de sessão finalizada. Consoles são ilimitados em todos os planos.'},
  {id: 'tv-fim-sessao', q: 'O que aparece na TV quando acaba o tempo do console?', alt: ['tela da tv no fim da sessao', 'resumo na tv', 'sessao finalizada na tv', 'acabou o tempo do console'], kw: ['tv', 'acaba', 'acabou', 'finalizada', 'resumo', 'console'],
    a: 'Quando a sessão do console termina, a TV abre a tela "Sessão finalizada" com a logo, o nome do cliente, a hora de início e de término, o tempo usado e o tempo que voltou para o saldo. Depois de 10 segundos o resumo some e entra um wallpaper em tela cheia, até a recepção liberar o console de novo (o tempo do cliente não fica exposto). No plano Pro, com Configuração › Personalizar visual, essa tela mostra a logo e a cor da sua arena.'},
  {id: 'vr', q: 'Funciona com VR e simuladores?', alt: ['oculus', 'simulador de corrida', 'realidade virtual'], kw: ['vr', 'simulador', 'simuladores', 'oculus', 'realidade'],
    a: 'Sim, ilimitados. VR e simuladores ligados a um PC usam o GameZoney Cliente; aparelhos ligados a uma TV pelo HDMI são controlados pela TV, como os consoles.'},
  {id: 'limite-pcs', q: 'Tem limite de PCs?', alt: ['quantas maquinas', 'quantos computadores posso ter', 'limite de estacoes'], kw: ['limite', 'quantos', 'quantas', 'maquinas', 'ilimitado'],
    a: 'Não. PCs, consoles, VR e simuladores são ilimitados em todos os planos.'},
  {id: 'cliente-pc', q: 'Como o cliente usa o PC?', alt: ['tela de login do pc', 'cliente entra com nick', 'bloqueio do pc', 'barra de tempo'], kw: ['login', 'nick', 'bloqueio', 'barra', 'tempo'],
    a: 'O PC fica bloqueado até a recepção liberar ou o cliente entrar com nick e senha. Durante a sessão aparece a barra de tempo; no fim, o PC bloqueia e limpa a sessão. Com o autoatendimento ligado, o cliente também pode criar a conta e pagar por PIX na própria tela.'},
  {id: 'desligar-pc', q: 'Posso desligar ou ligar os PCs pelo painel?', alt: ['ligar pela rede', 'wake on lan', 'reiniciar os pcs', 'desligar todos'], kw: ['desligar', 'ligar', 'reiniciar', 'wake'],
    a: 'Sim, em Ações dos PCs: Desligar, Reiniciar e Ligar (Wake-on-LAN, todos ou um específico). Ao desligar ou reiniciar pelo painel, a sessão é encerrada e o tempo restante volta ao saldo do cliente.'},
  {id: 'mensagem-pc', q: 'Consigo mandar mensagem para os PCs?', alt: ['aviso na tela', 'aviso de fim de tempo', 'avisar o cliente'], kw: ['mensagem', 'aviso', 'avisar'],
    a: 'Sim. Ações dos PCs › Enviar Mensagem mostra o aviso na tela dos PCs. Em Configuração › Avisos automáticos no PC você liga o aviso de fim de tempo (minutos antes) e o aviso do prêmio da fidelidade.'},
  {id: 'impressao', q: 'Como funciona o controle de impressão?', alt: ['controlar impressora', 'cobrar impressao', 'aprovar impressao'], kw: ['impressao', 'imprimir', 'impressora'],
    a: 'Com o Controle de impressão ligado (Configuração), todo trabalho de impressão dos PCs fica pausado até a recepção aprovar ou recusar no topo do Painel; ao aprovar, você pode cobrar pelo serviço. Disponível nos planos Standard e Pro.'},
  {id: 'diskless', q: 'Tem boot pela rede (diskless)?', alt: ['pc sem hd', 'iscsi', 'pxe'], kw: ['diskless', 'iscsi', 'pxe', 'boot'],
    a: 'Há uma pré-configuração em Configuração (produto, servidor iSCSI, PXE, imagem e PCs) com conferência da porta e dos MACs. A parte do boot em si é feita pelo seu software de diskless.'},

  // ---------- clientes, recargas, caixa e vendas ----------
  {id: 'recarga', q: 'Como faço uma recarga para o cliente?', alt: ['colocar tempo', 'adicionar credito', 'vender horas', 'liberar tempo'], kw: ['recarga', 'recarregar', 'credito', 'horas'],
    a: 'No Painel de controle ou em Clientes, escolha o cliente, clique em Recarga, informe o valor (ou promoção) e a forma de pagamento (Dinheiro, PIX, Cartão ou Pagamento combinado com até 3 formas). É preciso ter o caixa aberto.'},
  {id: 'visitante', q: 'Dá para atender cliente sem cadastro?', alt: ['visitante', 'cliente avulso', 'sem cadastro'], kw: ['visitante', 'avulso', 'cadastro'],
    a: 'Sim, como Visitante: no Painel, escolha o PC/console livre, Visitante, o valor ou tempo e a forma de pagamento. Também há Visitantes em grupo.'},
  {id: 'pix-pc', q: 'O cliente pode pagar por PIX no próprio PC?', alt: ['autoatendimento', 'pix na tela', 'cliente compra sozinho', 'criar conta no pc', 'pix automatico'], kw: ['pix', 'autoatendimento', 'sozinho'],
    a: 'Sim, com o Autoatendimento (Configuração › Autoatendimento): o cliente cria a conta e paga por PIX na tela do PC, escolhendo uma promoção ou "Outro valor". O pagamento cai na conta Mercado Pago da sua arena e o tempo entra sozinho. Disponível em todos os planos, inclusive no teste.'},
  {id: 'caixa', q: 'Como funciona o caixa?', alt: ['abrir caixa', 'fechar caixa', 'fechamento do dia', 'sangria'], kw: ['caixa', 'abrir', 'fechar', 'fechamento'],
    a: 'Em Caixa › Caixa atual você abre o caixa (com o valor inicial) e fecha no fim do turno; cada forma de pagamento é somada separadamente. Os caixas anteriores ficam em Caixas fechados.'},
  {id: 'pdv', q: 'Dá para vender produtos (lanchonete)?', alt: ['vender refrigerante', 'pdv', 'lanchonete', 'estoque de produtos', 'cadastrar produto'], kw: ['produtos', 'produto', 'pdv', 'lanchonete', 'estoque', 'vender'],
    a: 'Sim. Cadastre em Produtos/Serviços › Gerenciamento de Produtos (com código, código de barras, custo, preço e estoque) e venda em Caixa › Vendas (PDV), com leitor de código de barras e pagamento combinado. O estoque baixa sozinho.'},
  {id: 'importar-produtos', q: 'Posso importar meus produtos por planilha?', alt: ['planilha de produtos', 'excel de produtos'], kw: ['importar', 'planilha', 'excel', 'produtos'],
    a: 'Pode, em Gerenciamento de Produtos › Importar planilha: colunas Código, Nome, Categoria, Custo, Preço de venda e Margem (opcionais: Código de barras, Estoque, NCM, CFOP e CST/CSOSN). Produtos já existentes são atualizados.'},
  {id: 'codigo-barras', q: 'Funciona com leitor de código de barras?', alt: ['leitor de qr code', 'scanner', 'bipar produto'], kw: ['leitor', 'barras', 'scanner', 'qr'],
    a: 'Sim, em qualquer tela do painel: no PDV o produto entra no carrinho; em Produtos/Estoque abre o cadastro (ou oferece cadastrar); nas outras telas mostra o preço. Aceita código de barras e QR.'},
  {id: 'fidelidade', q: 'Como funciona a fidelidade?', alt: ['medalhas', 'pontos', 'programa de pontos', 'premio para clientes'], kw: ['fidelidade', 'medalhas', 'pontos', 'premio'],
    a: 'Em Fidelidade você define quantas medalhas o cliente ganha por valor gasto (por dia da semana) e o prêmio automático (minutos ao juntar X medalhas). Os resgates e o extrato ficam no cadastro do cliente. As medalhas só saem em recargas feitas com uma promoção e só depois que o programa é configurado em Fidelidade › Configurar programa: sem configurar, nenhuma medalha nem prêmio automático (vale também para quem atualizou de uma versão antiga). As medalhas do Corujão/Viradão ficam em Fidelidade › Medalhas Corujão/Viradão e começam em 0.'},
  {id: 'fidelidade-sem-configurar', q: 'O cliente ganhou medalhas e prêmio sem eu configurar a fidelidade', alt: ['fidelidade so quando voce configurar', 'medalhas sem configurar', 'ganhou 10 medalhas na promocao', 'resgate automatico sem configurar', 'promocao gerando medalhas', 'cancelar recarga que liberou o premio'], kw: ['medalhas', 'premio', 'resgate', 'configurar', 'promocao', 'automatico'],
    a: 'Isso acontecia em servidores instalados com versões antigas: valia uma regra padrão escondida (R$ 1 = 1 medalha e 10 medalhas = 60 minutos). Na versão atual, recargas com promoção só geram medalhas e o prêmio automático depois que você configura em Fidelidade › Configurar programa (tabela por dia da semana, medalhas necessárias e tempo do prêmio). Quem nunca configurou fica com o programa zerado; quem configurou de propósito vê a mesma regra na tabela por dia. As medalhas que os clientes já ganharam ficam no saldo. Para desfazer uma recarga que liberou o prêmio automático, cancele a fatura: o prêmio é desfeito junto (se o cliente ainda não usou o tempo).'},
  {id: 'corujao', q: 'O que é o Corujão/Viradão?', alt: ['evento', 'madrugada', 'virada'], kw: ['corujao', 'viradao', 'evento', 'madrugada'],
    a: 'É o evento de madrugada/virada: crie o evento, adicione os participantes, confirme o pagamento (entra no caixa), clique em Iniciar e depois Encerrar. Os participantes ganham as medalhas definidas em Fidelidade.'},
  {id: 'ranking', q: 'Tem ranking dos clientes?', alt: ['top clientes', 'melhores clientes'], kw: ['ranking', 'top'],
    a: 'Sim: Top 10 Medalhas, Top 10 Participação (Corujão/Viradão) e Top 10 Recargas do mês, no menu Ranking.'},
  {id: 'foto-cliente', q: 'Dá para cadastrar foto do cliente?', alt: ['foto pela camera', 'webcam'], kw: ['foto', 'camera', 'webcam'],
    a: 'Sim, no cadastro do cliente: tire pela câmera (webcam) ou envie um arquivo JPG/PNG.'},
  {id: 'exportar-clientes', q: 'Consigo exportar meus clientes?', alt: ['baixar lista de clientes', 'planilha de clientes'], kw: ['exportar', 'lista', 'clientes'],
    a: 'Sim, em Clientes › Exportar clientes (administrador; planilha Excel com nome, nick, CPF, telefone, e-mail, tempo, medalhas, observações e situação).'},
  {id: 'relatorios', q: 'O sistema tem relatórios?', alt: ['faturamento', 'estatisticas', 'relatorio do mes', 'quanto faturei'], kw: ['relatorio', 'relatorios', 'faturamento', 'estatistica', 'estatisticas'],
    a: 'Sim: Estatística (faturamento por dia, mês e ano, por forma de pagamento, PCs mais usados etc.), Faturas, Sessão, Log e Caixas fechados, com exportação.'},
  {id: 'funcionarios', q: 'Posso ter funcionários com acesso limitado?', alt: ['operador', 'usuario do funcionario', 'permissoes'], kw: ['funcionario', 'funcionarios', 'operador', 'permissao', 'permissoes'],
    a: 'Sim. Em Configuração › Contas de acesso você cria contas Administrador (tudo) ou Operador (atendimento: clientes, recargas, sessões, visitantes, PDV, histórico). Ações sensíveis (faturas, transferir/remover saldo, valor da hora, cancelamentos) pedem o administrador. Senhas de 8 a 24 caracteres (conta antiga com senha menor entra, mas o painel pede para trocar).'},
  {id: 'valor-hora', q: 'Como mudo o valor da hora?', alt: ['preco da hora', 'valor por hora'], kw: ['hora', 'valor'],
    a: 'No Painel de controle, clique na engrenagem do card "Valor da hora"; a mudança pede a senha do administrador.'},

  // ---------- segurança, backup e quedas ----------
  {id: 'backup', q: 'Como funciona o backup?', alt: ['copia de seguranca', 'restaurar backup', 'onde fica o backup'], kw: ['backup', 'restaurar', 'copia'],
    a: 'O backup automático fica em Documentos\\gamezoney\\backup (os automáticos com mais de 7 dias são apagados; os manuais ficam). Em Configuração › Backup você cria um backup manual e restaura. Guarde também uma cópia fora do computador (pendrive ou nuvem).'},
  {id: 'queda-internet', q: 'E se a internet ou a energia cair?', alt: ['caiu a internet', 'queda de energia', 'sem internet', 'faltou luz'], kw: ['internet', 'energia', 'luz', 'queda', 'caiu'],
    a: 'Queda de internet não encerra sessão: o sistema funciona na rede local. Se um PC perde a conexão, ele fica vermelho no painel e a sessão continua contando. Se o servidor reiniciar, ele espera os PCs voltarem. Notas fiscais e PIX pendentes saem sozinhos quando a internet volta.'},
  {id: 'dados-seguros', q: 'Meus dados ficam seguros?', alt: ['lgpd', 'privacidade', 'onde ficam os dados'], kw: ['seguranca', 'lgpd', 'privacidade', 'dados'],
    a: 'Os dados da arena ficam no PC da recepção (e nos seus backups), não na internet. O site usa HTTPS e os pagamentos são feitos pelo Mercado Pago. Política completa em gamezoney.com/privacidade.html.'},
  {id: 'atualizar', q: 'Como atualizo o GameZoney?', alt: ['nova versao', 'atualizacao do sistema', 'update'], kw: ['atualizar', 'atualizacao', 'versao', 'update'],
    a: 'Baixe o GameZoney-Instalador.exe mais recente em Minha conta › Downloads e instale por cima, no servidor e nos PCs (os dados são mantidos). As novidades ficam em gamezoney.com/atualizacoes.html.'},
  {id: 'desinstalar', q: 'Como desinstalo?', alt: ['remover o sistema', 'desinstalar cliente'], kw: ['desinstalar', 'desinstalo', 'remover'],
    a: 'Pelo Windows (Aplicativos instalados › GameZoney). No Servidor, a desinstalação pergunta se deve apagar os dados; os backups em Documentos\\gamezoney\\backup são mantidos.'},
  {id: 'senha-admin', q: 'Esqueci a senha do administrador do painel.', alt: ['nao consigo entrar no painel', 'senha do servidor', 'clearad', 'redefinir senha do administrador', 'resetar senha do admin', 'esqueci a senha do servidor'], kw: ['senha', 'administrador', 'painel', 'clearad', 'esqueci', 'resetar'],
    a: 'Use o ClearAd, no computador do servidor: encerre o servidor (ícone do GameZoney ao lado do relógio › Sair), abra o arquivo ClearAd.exe na pasta de instalação do servidor (%LOCALAPPDATA%\\Programs\\GameZoneyServidor; ele não fica no menu Iniciar), digite a nova senha duas vezes (8 a 24 caracteres) e confirme. Só a senha do administrador principal muda; clientes, vendas e configurações continuam iguais, a troca fica no Log e uma cópia dos dados de antes é guardada. Com o servidor aberto ele não faz nada. A senha nunca pode ser vista pelo site. Se precisar de ajuda, peça um especialista.'},

  // ---------- fiscal ----------
  {id: 'fiscal', q: 'O GameZoney emite nota fiscal?', alt: ['voces emitem nota fiscal', 'o sistema emite nota', 'nota fiscal', 'cupom fiscal', 'emite nfc-e', 'emite nfs-e', 'sefaz', 'duvida fiscal', 'imposto', 'invoice', 'factura'], kw: ['fiscal', 'nota', 'notas', 'nfce', 'nfse', 'sefaz', 'imposto', 'cupom', 'tributario', 'emite', 'emitem', 'invoice', 'factura'],
    a: 'No plano Pro, sim: o GameZoney emite NFC-e para os produtos vendidos no PDV e NFS-e para as recargas de tempo e os serviços, pela Focus NFe, direto com a Sefaz e a prefeitura. Também importa o XML da NF-e dos fornecedores para dar entrada no estoque. Sem o Pro, o comprovante impresso é um comprovante interno, sem valor fiscal.\nRegime tributário, alíquotas e obrigações da sua cidade e do seu estado devem ser confirmados com o seu contador; o GameZoney ajuda com os relatórios de faturamento por dia, mês e ano, por forma de pagamento, e com o fechamento de caixa.'},
  {id: 'focus', q: 'O que preciso para emitir notas fiscais?', alt: ['focus nfe', 'certificado digital', 'certificado a1', 'csc', 'inscricao municipal'], kw: ['focus', 'certificado', 'a1', 'csc', 'inscricao', 'emitir'],
    a: 'No plano Pro, a arena precisa de: conta na Focus NFe (contratada e paga direto pela arena) com o certificado digital A1 da empresa enviado lá; inscrição estadual e CSC da Sefaz (NFC-e); inscrição municipal (NFS-e), com a cidade atendida pela Focus. Os códigos fiscais (NCM, CFOP, CST/CSOSN, item de serviço, alíquota do ISS) são passados pelo contador. Depois é só configurar em Gerenciamento NF-e › Configuração fiscal.'},
  {id: 'nfe-entrada', q: 'Como funciona a importação do XML da NF-e?', alt: ['xml do fornecedor', 'entrada de nota', 'nota de entrada'], kw: ['xml', 'fornecedor', 'entrada'],
    a: 'No Pro, em Gerenciamento NF-e › Notas de entrada: importe o XML da nota do fornecedor, vincule cada item ao produto (por código, código de barras ou vínculo lembrado; caixas/pacotes são convertidos em unidades) e clique em Dar entrada: o estoque e o custo são atualizados.'},
  {id: 'mei', q: 'Sou MEI. Posso usar?', alt: ['simples nacional', 'regime tributario', 'cnpj'], kw: ['mei', 'simples', 'regime', 'cnpj'],
    a: 'Pode usar o GameZoney normalmente. Para emitir notas no Pro, a configuração fiscal aceita Simples Nacional, MEI ou regime normal, mas o que a sua empresa precisa emitir depende da sua cidade e do seu regime: confirme com o seu contador.'},

  // ---------- Pro: unidades e app ----------
  {id: 'multi-unidade', q: 'Tenho mais de uma loja. Como acompanho?', alt: ['varias unidades', 'filiais', 'multi unidade', 'duas lojas', 'mais de 5 unidades', 'limite de unidades', 'quantas unidades posso ter'], kw: ['unidade', 'unidades', 'lojas', 'filial', 'filiais'],
    a: 'No Pro, o Multi-Unidade envia um resumo de cada loja (faturamento do dia e do mês, caixa, PCs em uso, clientes ativos, produtos sem estoque) para gamezoney.com › Minha conta › Unidades. Cada loja tem o próprio servidor e precisa de internet. Ligue em Configuração › Multi-Unidade. Cada conta registra até 5 unidades; para mais, abra um chamado em Minha conta › Suporte ou escreva para suporte@gamezoney.com.'},
  {id: 'personalizar-visual', q: 'Posso colocar a logo e as cores da minha arena no sistema?', alt: ['trocar a logo do gamezoney', 'layout personalizado', 'personalizar o visual', 'mudar as cores do painel', 'minha marca no sistema', 'logo nos pcs', 'logo na tv do console', 'tela da tv quando acaba o tempo'], kw: ['logo', 'cor', 'cores', 'layout', 'visual', 'marca', 'personalizar', 'personalizado'],
    a: 'Pode, no plano Pro: em Configuração › Personalizar visual, envie a logo da arena em PNG (até 1 MB) e escolha a cor de destaque (o sistema sugere a cor a partir da logo). O painel da recepção, a tela dos PCs e a tela da TV no fim da sessão passam a mostrar a sua logo e a sua cor; o fundo escuro e os avisos continuam iguais. Os PCs aplicam quando o GameZoney Cliente abrir de novo; a TV e o app do cliente, na hora (o app mostra a logo dos PCs no lugar do ícone GZ). Tamanho ideal: logo do Servidor horizontal 960 × 250 px; logo dos PCs (também TV e app) quadrada 512 × 512 px; PNG com fundo transparente. Para voltar, use "Voltar ao padrão GameZoney".'},
  {id: 'configuracao-abas', q: 'Como encontro as áreas da Configuração?', alt: ['configuracao em abas', 'nao acho a configuracao do backup', 'onde fica o autoatendimento na configuracao', 'configuracao organizada', 'abas da configuracao'], kw: ['configuracao', 'abas', 'aba', 'areas', 'encontrar', 'organizada'],
    a: 'A Configuração do painel é dividida em abas no topo, como no Caixa: Licença, Personalizar visual, Contas de acesso, Máquinas, Backup, Servidor IP, Autoatendimento, Avisos no PC, Impressão, Boot pela rede e Multi-Unidade. Clique na aba para ver só aquela área, sem rolar a página; o painel lembra a última aba aberta. O nome da arena fica no Perfil.'},
  {id: 'servidor-abre-rapido', q: 'O servidor demora para abrir ou fechar?', alt: ['servidor lento para abrir', 'gamezoney demora para iniciar', 'demora para encerrar o servidor', 'abrir e fechar mais rapido', 'programa pesado'], kw: ['demora', 'lento', 'abrir', 'iniciar', 'encerrar', 'fechar', 'rapido', 'pesado'],
    a: 'Não deve: o GameZoney Servidor abre em 1 a 2 segundos, mesmo com anos de dados, e encerra em poucos segundos (a janela do painel some na hora e aparece "Encerrando o servidor…"). Na primeira abertura depois de instalar pode levar um pouco mais, porque o antivírus examina os arquivos novos. Se estiver demorando sempre, instale o GameZoney-Instalador.exe mais recente e, se continuar, fale com o suporte.'},
  {id: 'nome-arena', q: 'Posso colocar o nome da minha arena no cupom?', alt: ['nome da loja no cupom', 'trocar gamezoney do cupom', 'nome da organizacao nos relatorios', 'personalizar cupom', 'onde fica o nome da arena', 'nome da arena no perfil'], kw: ['cupom', 'nome', 'arena', 'organizacao', 'loja', 'relatorio'],
    a: 'Pode, em todos os planos: clique em Perfil (ao lado de Sair) e preencha o campo Arena/Organização no topo (só o administrador muda). O nome sai no cupom de venda, no fechamento de caixa, nas faturas, no relatório financeiro e no nome das planilhas exportadas. Em branco, sai GameZoney.'},
  {id: 'app-cliente', q: 'Como funciona o app do cliente?', alt: ['app para os clientes', 'app.gamezoney.com', 'cliente ver o saldo pelo celular', 'aplicativo da arena', 'cliente ver estacoes livres', 'app do cliente', 'link do app da arena'], kw: ['app', 'aplicativo', 'celular', 'cliente', 'saldo', 'estacoes', 'link'],
    a: 'No plano Pro, ligue em Gerenciar App › App do cliente e escolha o endereço (ex.: arena-centro). O link fica app.gamezoney.com/arena-centro. O cliente entra com o mesmo nick e senha do PC e vê: Início (saldo de tempo, medalhas e o tempo da sessão), Estações (PCs, consoles/VR e simuladores livres ou ocupados, com o tempo que falta), Conquistas, Ranking (Top 10 de medalhas, Corujão/Viradão e recargas do mês) e Histórico. Não precisa de domínio, VPS nem abrir portas: o servidor se liga sozinho ao gamezoney.com. O app só mostra informações; recargas continuam na recepção e no PC.'},
  {id: 'conquistas', q: 'Como criar conquistas para os clientes?', alt: ['conquistas', 'criar conquista', 'medalhas por horas jogadas', 'premiar cliente que joga muito', 'achievements'], kw: ['conquista', 'conquistas', 'meta', 'medalhas', 'premiar'],
    a: 'No plano Pro, em Gerenciar App › Conquistas › + Nova conquista: escolha o ícone, o nome, o que o cliente precisa (horas jogadas, sessões, participações em Corujão/Viradão ou valor em recargas), a meta e as medalhas. Quando o cliente completa, as medalhas entram na Fidelidade e aparece o aviso no PC; quem já cumpre a meta recebe na hora. O cliente acompanha o progresso no app (app.gamezoney.com).'},
  {id: 'tipo-estacao', q: 'Como aparecem VR e simuladores no app?', alt: ['filtro vr simulador', 'tipo da estacao no app', 'cadastrar vr', 'cadastrar simulador', 'foto do xbox no app', 'foto do playstation no app', 'console vr'], kw: ['vr', 'simulador', 'simuladores', 'filtro', 'tipo'],
    a: 'Ao configurar a estação (Painel de controle › clicar na estação ou + Nova estação), o plano Pro mostra "Tipo no app do cliente": computador pode ser PC, Console/VR ou Simulador; console pode ser Console/VR ou Simulador. VR fica junto com console (Console/VR). É esse tipo que aparece no filtro e na foto de Estações do app: console/VR com Xbox no nome mostra a foto do Xbox; com PS3, PS4, PS5 ou PlayStation (ou sem marca), a do PlayStation.'},
  {id: 'app-topo', q: 'O topo do app ficou fixo por cima da tela', alt: ['topo do app que rola com a página', 'topo do app mais limpo', 'online do lado do nome', 'nome da arena fixo no app', 'cabecalho do app'], kw: ['topo', 'fixo', 'online', 'cabecalho', 'nome'],
    a: 'No app do cliente (app.gamezoney.com), o topo com o ícone/logo e o nome da arena agora rola junto com a página: não fica mais fixo por cima do conteúdo. O aviso Online fica no canto direito, na mesma linha do nome da arena. Se ainda aparecer do jeito antigo, recarregue a página uma vez.'},
  {id: 'app-visual', q: 'Como é o visual do app do cliente?', alt: ['novo visual do app do cliente', 'cor do app', 'app azul', 'foto das estacoes no app'], kw: ['visual', 'cor', 'fotos', 'app', 'dourado'],
    a: 'O app do cliente tem o visual preto e dourado do GameZoney: ícone GZ e o nome da arena no topo, com Online no canto direito (o topo rola junto com a página, não fica fixo por cima do conteúdo), fundo com partículas, estações com foto (PC, Xbox, PlayStation e simulador), conquistas em cartões transparentes e histórico em lista. Se a arena usa o Personalizar visual (plano Pro), o app troca o dourado pela cor da arena (ex.: azul) em todo o efeito e mostra a logo dela.'},
  {id: 'ranking-app', q: 'O cliente vê o ranking no app?', alt: ['ranking no app', 'top 10 no celular', 'ranking para os clientes', 'cliente ver o ranking'], kw: ['ranking', 'top', 'app', 'celular', 'posicao'],
    a: 'Sim, no plano Pro. No app do cliente (app.gamezoney.com/endereço-da-arena), a aba Ranking mostra os mesmos Top 10 do painel: Medalhas, Corujão/Viradão e Recargas do mês. Aparece só o nick de cada cliente (sem nome completo) e, nas recargas, a quantidade, sem valores em reais. A linha do próprio cliente fica marcada como "você".'},
  {id: 'tamanho-logo', q: 'Qual o tamanho ideal da logo?', alt: ['tamanho da logo', 'medida da logo', 'resolucao da logo', 'logo quadrada ou horizontal', 'logo no app do cliente'], kw: ['tamanho', 'medida', 'resolucao', 'logo', 'pixels', 'px'],
    a: 'Em Configuração › Personalizar visual (plano Pro): logo do Servidor (painel, canto superior esquerdo) horizontal, 960 × 250 px (proporção 4:1); logo dos PCs (também na tela da TV e no app do cliente) quadrada, 512 × 512 px. Use PNG com fundo transparente, desenho centralizado e pouca margem, até 1 MB. Se usar a mesma logo nos dois, prefira a quadrada: logo muito larga e baixa aparece pequena nos PCs e no app. Trocar a logo troca também no app do cliente, sozinho.'},
  {id: 'app-recepcao', q: 'Posso usar o painel do servidor fora da arena (app da recepção)?', alt: ['app da recepcao', 'app servidor', 'painel pelo celular', 'acessar o painel de casa', 'abrir o servidor de fora', 'painel do servidor no celular', 'acesso remoto ao painel', 'app.gamezoney.com/servidor'], kw: ['recepcao', 'painel', 'remoto', 'fora', 'celular', 'casa', 'servidor'],
    a: 'Sim, no plano Pro. Em Gerenciar App, escolha o endereço na aba App do cliente e, na aba App da recepção, marque Ligar o app da recepção, escolha quem pode entrar (todos os usuários do painel ou só administradores) e salve. O painel abre em app.gamezoney.com/servidor/ seguido do endereço (ex.: app.gamezoney.com/servidor/arena-centro), no celular, notebook ou outro computador, com o mesmo usuário e senha do painel. Ficam todas as telas, menos Configuração e Gerenciar App, que só abrem no próprio servidor. Não precisa abrir porta no roteador: o servidor precisa estar aberto e com internet. Segurança: o acesso cai depois de 12 horas sem uso, a senha precisa ter pelo menos 8 caracteres, a entrada pede um código de 6 dígitos enviado ao e-mail da conta gamezoney.com do plano (quem trabalha na recepção pede o código ao dono da conta), a senha passa pelo gamezoney.com dentro do HTTPS e não é gravada no site, 5 senhas erradas travam o usuário por 15 minutos, cada entrada fica no Log com o IP e o botão Desconectar todos derruba os acessos na hora.'},
  {id: 'porta-app', q: 'Preciso abrir porta no roteador para o app funcionar?', alt: ['testar conexao no gerenciar app', 'botao testar conexao', 'abrir porta', 'liberar porta no roteador', 'redirecionar porta', 'port forwarding', 'testar conexao do app', 'app nao conecta', 'app da recepcao nao conecta', 'firewall do app'], kw: ['porta', 'portas', 'roteador', 'firewall', 'conectar', 'conexao', 'liberar'],
    a: 'Não. O app do cliente e o app da recepção não precisam de porta aberta no roteador nem de IP fixo: o GameZoney Servidor só faz uma conexão de saída HTTPS (porta 443) até o gamezoney.com, e o instalador já libera essa saída no firewall do Windows. Se não conectar, use Gerenciar App › Testar conexão: ele confere a internet, a saída HTTPS, a conta do plano Pro, o endereço e a ligação, e diz o que corrigir (por exemplo, antivírus bloqueando ou interceptando o HTTPS). Se precisar refazer o firewall: menu Iniciar › GameZoney › Reparar conexão de rede.'},
  {id: 'assistente-demora', q: 'Por que o assistente demora um pouco para responder?', alt: ['assistente lendo a mensagem', 'atendimento mais natural no chat', 'bolinha girando no chat', 'o chat demora'], kw: ['demora', 'lendo', 'assistente', 'girando', 'espera'],
    a: 'O assistente virtual lê a sua mensagem antes de responder: leva de 2 a 3 segundos e, enquanto isso, aparece "Assistente está lendo sua mensagem…" com um indicador girando. A resposta vem logo em seguida. Se quiser falar com uma pessoa, use "Falar com especialista".'},
  {id: 'requisitos-pro', q: 'O que preciso ter antes de assinar o Pro?', alt: ['requisitos do pro', 'dominio', 'vps', 'ip fixo'], kw: ['dominio', 'vps', 'fixo', 'requisitos'],
    a: 'Para usar tudo do Pro: internet na arena (app do cliente e Multi-Unidade), conta na Focus NFe com certificado A1 (notas de venda) e o XML da NF-e do fornecedor (entrada de estoque). O app do cliente funciona em app.gamezoney.com e não precisa de domínio, VPS nem IP fixo. A Focus NFe é contratada à parte.'},

  // ---------- atendimento ----------
  {id: 'suporte', q: 'Como falo com o suporte?', alt: ['abrir chamado', 'preciso de ajuda', 'estou com problema', 'deu erro', 'suporte tecnico'], kw: ['suporte', 'chamado', 'ajuda', 'problema', 'erro', 'bug'],
    a: 'Se você já usa o GameZoney, abra um chamado em Minha conta › Suporte (pode anexar até 2 imagens) e acompanhe a resposta por lá e por e-mail. Também atendemos pelo e-mail suporte@gamezoney.com. Para falar agora com uma pessoa, escreva "falar com especialista".'},
  {id: 'chat-encerrado', q: 'O chat fechou sozinho. O que aconteceu?', alt: ['a conversa foi encerrada', 'nao consigo mandar mensagem no chat', 'chat encerrado por falta de resposta', 'conversa fechou'], kw: ['fechou', 'encerrada', 'encerrou', 'sozinho', 'chat', 'conversa'],
    a: 'Quando o cliente não responde o assistente em 10 minutos (sem ter pedido um especialista), a conversa é encerrada. Para continuar, clique em "Abrir nova conversa". Se você pediu um especialista, a conversa fica aberta esperando o atendente. No fim, use "Encerrar e avaliar" para dar a sua nota.'},
  {id: 'servidor-lento', q: 'O servidor demora para abrir ou encerrar.', alt: ['servidor demorando para fechar', 'demora para abrir o gamezoney', 'encerrar servidor travado', 'servidor lento para iniciar'], kw: ['demora', 'demorando', 'lento', 'abrir', 'encerrar', 'fechar', 'iniciar'],
    a: 'Instale o GameZoney-Instalador.exe mais recente (Minha conta › Downloads) por cima: as versões novas abrem e encerram em poucos segundos, mostram "Encerrando o servidor…" e, se algo travar, fecham sozinhas em até 4 segundos. As sessões continuam contando e são retomadas ao abrir. Se continuar lento, abra um chamado em Minha conta › Suporte.'},
  {id: 'horario', q: 'Qual o horário de atendimento?', alt: ['que horas vocês atendem', 'atendem no fim de semana'], kw: ['horario', 'horas', 'atendem', 'sabado', 'domingo'],
    a: 'O assistente responde a qualquer hora. Os especialistas atendem em dias úteis; o topo do chat mostra quando há alguém online. Fora desse horário, deixe sua mensagem: respondemos por e-mail.'},
  {id: 'contato', q: 'Quais são os contatos da GameZoney?', alt: ['email de contato', 'whatsapp', 'telefone', 'instagram'], kw: ['contato', 'email', 'whatsapp', 'telefone', 'instagram'],
    a: 'E-mail: suporte@gamezoney.com. Instagram: @gamezoney_. Clientes: Minha conta › Suporte. E aqui no chat, a qualquer hora.'},
  {id: 'avaliar-app', q: 'Como avalio o GameZoney?', alt: ['deixar avaliacao', 'depoimento'], kw: ['avaliar', 'avaliacao', 'depoimento'],
    a: 'Em Minha conta › Avaliar: de 1 a 5 estrelas, texto e até 2 imagens. Depois de enviada, você pode editar a avaliação uma vez. Ela não é excluída pelo site; se precisar retirar, fale com o suporte. Obrigado por ajudar!'},
  {id: 'conta-carregando', q: 'Minha conta fica em Carregando sua conta', alt: ['minha conta abre sem travar', 'carregando sua conta', 'minha conta não abre', 'conta travada carregando', 'pagina da conta nao carrega'], kw: ['carregando', 'travar', 'travada', 'conta', 'abre'],
    a: 'Isso foi corrigido: depois de uma atualização do site, o navegador podia usar uma parte antiga da página e Minha conta ficava em "Carregando sua conta…". Se ainda acontecer, recarregue a página uma vez (no celular, puxe a tela para baixo; no computador, Ctrl+F5). Se aparecer "Não foi possível carregar sua conta", toque em Tentar novamente. Persistindo, fale com um especialista por aqui.'},
  {id: 'atalho-app', q: 'Onde fica o botão do app na minha conta?', alt: ['atalho para o app na sua conta', 'abrir o app pela minha conta', 'link do app.gamezoney.com', 'botao do app', 'onde abro o app'], kw: ['atalho', 'botao', 'app', 'conta', 'abrir'],
    a: 'Em Minha conta › Visão geral há o botão "Ir para o app.gamezoney.com" (e o atalho "Abrir o app.gamezoney.com"). Lá ficam o app do cliente (app.gamezoney.com/endereço-da-arena) e o app da recepção (app.gamezoney.com/servidor/endereço-da-arena), do plano Pro. O endereço da arena é escolhido no GameZoney Servidor, em Gerenciar App › App do cliente.'},
];
